# Prints two fresh secrets for your .env file, generated by the operating system's cryptographic RNG.
# Copy them into .env. Do not paste them into chats, tickets or Git.
function New-RandomBase64([int]$Bytes) {
    $buffer = New-Object byte[] $Bytes
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    try { $rng.GetBytes($buffer) } finally { $rng.Dispose() }
    return [Convert]::ToBase64String($buffer)
}

Write-Host "SILENTECHO_HMAC_SECRET=$(New-RandomBase64 48)"
Write-Host "SILENTECHO_ENCRYPTION_KEY=$(New-RandomBase64 32)"
